            var mockRuleRepo = new Mock<IRuleRepository>();
            var mockCatRepo = new Mock<ICategoryRepository>();
            
            var category = new CategoryNode("TestCategory");
            
            mockCatRepo.Setup(r => r.GetAllAsync(It.IsAny<bool>()))
