            var viewModel = new DictionaryEditorViewModel(mockRuleRepo.Object, mockCatRepo.Object);
            await viewModel.InitializeAsync();

            // Act
            viewModel.SelectedCategory = category;
            viewModel.SubjectKeywordsInput = " keyword1 , keyword2 ";
            viewModel.SenderKeywordsInput = "boss@corp.com";
            
            await viewModel.CreateRuleFromFormAsync();

            // Assert
            mockRuleRepo.Verify(r => r.AddDictionaryRuleAsync(It.Is<DictionaryRule>(rule => 
